-- Frozen former query for /api/chapter/feed?tlang=es&limit=100, page1.
-- A measured cancellation is an observation, not a reason to widen its budget.
WITH matched AS(SELECT  c.id,c.manga_id,c.published_at AS sort_value,''::text AS sort_text FROM platform.catalog_chapters c JOIN platform.catalog_manga m ON m.id=c.manga_id LEFT JOIN platform.catalog_chapter_counters s ON s.chapter_id=c.id WHERE c.deleted_at IS NULL AND m.deleted_at IS NULL AND m.state='published' AND platform.protocol_source_is_visible(c.protocol_event_id) AND c.language=ANY($1) AND m.content_rating=ANY($2) AND m.protocol_source_visible AND platform.protocol_source_is_visible(m.protocol_series_id) ),selected AS(SELECT * FROM matched ORDER BY sort_value DESC NULLS LAST,sort_text DESC,id LIMIT $3 OFFSET $4) SELECT jsonb_build_object('total',(SELECT count(*) FROM matched),'limit',100,'page',1,'data',COALESCE((SELECT jsonb_agg(platform.catalog_chapter_json(id) || jsonb_build_object('_sort_value',sort_value,'_sort_text',sort_text) ORDER BY sort_value DESC NULLS LAST,sort_text DESC,id) FROM selected),'[]'::jsonb),'map',jsonb_build_object('manga',COALESCE((SELECT jsonb_object_agg(manga_id,platform.catalog_manga_json(manga_id)) FROM(SELECT DISTINCT manga_id FROM selected)ids),'{}'::jsonb)))
